import type { Zone } from '@/lib/domain/types';
import { useSettings } from '@/lib/store/settings-store';
import { createAudioPlayer, setAudioModeAsync, type AudioPlayer } from 'expo-audio';
import * as Haptics from 'expo-haptics';

/**
 * Door sounds and the small haptic tap that goes with them. Sounds are generated by
 * scripts/make-door-sounds.mjs: a rubber seal and compressor hum for the fridge, a seal and cold hiss for
 * the freezer, a creaking hinge and a wooden knock for the pantry. Everything here is best effort:
 * no audio device, autoplay rules or a missing vibration motor must never break opening a door.
 */

type Action = 'open' | 'close';

const SOURCES: Record<Zone, Record<Action, number>> = {
  fridge: { open: require('@/assets/sounds/fridge-open.wav'), close: require('@/assets/sounds/fridge-close.wav') },
  freezer: { open: require('@/assets/sounds/freezer-open.wav'), close: require('@/assets/sounds/freezer-close.wav') },
  pantry: { open: require('@/assets/sounds/pantry-open.wav'), close: require('@/assets/sounds/pantry-close.wav') },
};

/** Quiet: UI sounds should sit under whatever the user is listening to, not over it. */
const VOLUME = 0.55;

const players = new Map<string, AudioPlayer>();
let modeSet = false;

function player(zone: Zone, action: Action): AudioPlayer {
  const key = `${zone}-${action}`;
  let p = players.get(key);
  if (!p) {
    if (!modeSet) {
      modeSet = true;
      // Mix with the user's music instead of pausing it, and stay silent when the phone is on silent.
      void setAudioModeAsync({ interruptionMode: 'mixWithOthers', playsInSilentMode: false }).catch(() => {});
    }
    p = createAudioPlayer(SOURCES[zone][action]);
    p.volume = VOLUME;
    players.set(key, p);
  }
  return p;
}

/** Plays the door's sound and a light tap. Does nothing when "Sounds and vibration" is off. */
export function doorFeedback(zone: Zone, action: Action) {
  if (!useSettings.getState().settings.soundEffects) return;
  try {
    const p = player(zone, action);
    void p.seekTo(0).catch(() => {});
    p.play();
  } catch {
    // No audio available. The door still opens.
  }
  // Opening is a light tap, shutting a slightly firmer one, like the real thing.
  void Haptics.impactAsync(action === 'open' ? Haptics.ImpactFeedbackStyle.Light : Haptics.ImpactFeedbackStyle.Medium).catch(() => {});
}
